def resolve_module(family: str, operation: str):
    """Fail closed on unsupported input; import only an approved literal path."""
    if type(family) is not str or family not in FAMILIES:
        raise CognitionError("unregistered capability family")
    if type(operation) is not str or operation not in OPERATIONS:
        raise CognitionError("unknown operational boundary")
    try:
        loader = _LOADERS[(family, operation)]
    except KeyError as exc:
        raise CognitionError("missing approved module identity") from exc
    return loader()


__all__ = ("OPERATIONS", "resolve_module")
